103	  type MigrationSummary =
104	    | "skipped"
105	    | "already applied"
106	    | "applied (empty database)"
107	    | "applied (pending migrations)";
108	  
109	  function formatPendingMigrationSummary(migrations: string[]): string {
110	    if (migrations.length === 0) return "none";
111	    return migrations.length > 3
112	      ? `${migrations.slice(0, 3).join(", ")} (+${migrations.length - 3} more)`
113	      : migrations.join(", ");
114	  }
