116	  async function promptApplyMigrations(migrations: string[]): Promise<boolean> {
117	    if (process.env.PAPERCLIP_MIGRATION_AUTO_APPLY === "true") return true;
118	    if (process.env.PAPERCLIP_MIGRATION_PROMPT === "never") return false;
119	    if (!stdin.isTTY || !stdout.isTTY) return true;
120	  
121	    const prompt = createInterface({ input: stdin, output: stdout });
122	    try {
123	      const answer = (await prompt.question(
124	        `Apply pending migrations (${formatPendingMigrationSummary(migrations)}) now? (y/N): `,
125	      )).trim().toLowerCase();
126	      return answer === "y" || answer === "yes";
127	    } finally {
128	      prompt.close();
129	    }
130	  }
