136	  async function ensureMigrations(
137	    connectionString: string,
138	    label: string,
139	    opts?: EnsureMigrationsOptions,
140	  ): Promise<MigrationSummary> {
141	    const autoApply = opts?.autoApply === true;
142	    let state = await inspectMigrations(connectionString);
143	    if (state.status === "needsMigrations" && state.reason === "pending-migrations") {
144	      const repair = await reconcilePendingMigrationHistory(connectionString);
145	      if (repair.repairedMigrations.length > 0) {
146	        logger.warn(
147	          { repairedMigrations: repair.repairedMigrations },
148	          `${label} had drifted migration history; repaired migration journal entries from existing schema state.`,
149	        );
150	        state = await inspectMigrations(connectionString);
151	        if (state.status === "upToDate") return "already applied";
152	      }
153	    }
154	    if (state.status === "upToDate") return "already applied";
155	    if (state.status === "needsMigrations" && state.reason === "no-migration-journal-non-empty-db") {
156	      logger.warn(
157	        { tableCount: state.tableCount },
158	        `${label} has existing tables but no migration journal. Run migrations manually to sync schema.`,
159	      );
160	      const apply = autoApply ? true : await promptApplyMigrations(state.pendingMigrations);
161	      if (!apply) {
162	        throw new Error(
163	          `${label} has pending migrations (${formatPendingMigrationSummary(state.pendingMigrations)}). ` +
164	            "Refusing to start against a stale schema. Run pnpm db:migrate or set PAPERCLIP_MIGRATION_AUTO_APPLY=true.",
165	        );
166	      }
167	  
168	      logger.info({ pendingMigrations: state.pendingMigrations }, `Applying ${state.pendingMigrations.length} pending migrations for ${label}`);
169	      await applyPendingMigrations(connectionString);
170	      return "applied (pending migrations)";
171	    }
172	  
173	    const apply = autoApply ? true : await promptApplyMigrations(state.pendingMigrations);
174	    if (!apply) {
175	      throw new Error(
176	        `${label} has pending migrations (${formatPendingMigrationSummary(state.pendingMigrations)}). ` +
177	          "Refusing to start against a stale schema. Run pnpm db:migrate or set PAPERCLIP_MIGRATION_AUTO_APPLY=true.",
178	      );
179	    }
